from typing import List

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)
        INF = float('inf')
        # state: (j, a) -> min cost of closed subarrays; j = number of subarrays started
        states = {(1, nums[0]): 0}
        for i in range(1, n):
            x = nums[i]
            new = {}
            def upd(key, val):
                if val < new.get(key, INF):
                    new[key] = val
            for (j, a), c in states.items():
                # extend current subarray
                upd((j, a & x), c)
                # close current subarray (value a) and start new one at x
                if j < m and a == andValues[j - 1]:
                    upd((j + 1, x), c + a)
            states = new
            if not states:
                return -1
        best = INF
        for (j, a), c in states.items():
            if j == m and a == andValues[m - 1]:
                best = min(best, c + a)
        return best if best != INF else -1
