class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        INF = float('inf')
        n = len(nums)
        m = len(andValues)
        # dp_prev[j] = dp[i-1][j]
        dp_prev = [INF] * (m + 1)
        dp_prev[0] = 0
        # D[j]: AND value of segment (start l .. current end) -> min dp[l][j-1]
        D = [dict() for _ in range(m + 1)]
        for i in range(1, n + 1):
            x = nums[i - 1]
            newD = [dict() for _ in range(m + 1)]
            for j in range(1, m + 1):
                nd = {}
                for a, v in D[j].items():
                    b = a & x
                    if b in nd:
                        if v < nd[b]:
                            nd[b] = v
                    else:
                        nd[b] = v
                pv = dp_prev[j - 1]
                if pv < INF:
                    if x in nd:
                        if pv < nd[x]:
                            nd[x] = pv
                    else:
                        nd[x] = pv
                newD[j] = nd
            dp_cur = [INF] * (m + 1)
            dp_cur[0] = INF
            for j in range(1, m + 1):
                t = andValues[j - 1]
                if t in newD[j]:
                    dp_cur[j] = newD[j][t] + x
            D = newD
            dp_prev = dp_cur
        res = dp_prev[m]
        return -1 if res == INF else int(res)
