class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        INF = float('inf')
        n = len(nums)
        m = len(andValues)
        prevD = [INF] * (m + 1)
        prevD[0] = 0
        S = [dict() for _ in range(m + 1)]
        for i in range(n):
            x = nums[i]
            newS = [dict() for _ in range(m + 1)]
            newD = [INF] * (m + 1)
            for j in range(1, m + 1):
                d = {}
                for a, v in S[j].items():
                    key = a & x
                    if key in d:
                        if v < d[key]:
                            d[key] = v
                    else:
                        d[key] = v
                base = prevD[j - 1]
                if base < INF:
                    if x in d:
                        if base < d[x]:
                            d[x] = base
                    else:
                        d[x] = base
                newS[j] = d
                target = andValues[j - 1]
                if target in d:
                    newD[j] = d[target] + x
            S = newS
            prevD = newD
        res = prevD[m]
        return -1 if res == INF else int(res)

