        if not (1 <= n <= 10**4):
            return False
        if not (1 <= m <= min(n, 10)):
            return False
        if not all(isinstance(x, int) and not isinstance(x, bool) and 1 <= x < 10**5 for x in nums):
            return False
        if not all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x < 10**5 for x in andv):
            return False
        return True
