    nums = json.loads(lines[0])
    andv = json.loads(lines[1])
    n, m = len(nums), len(andv)
    INF = float("inf")

    # f(i, j): minimal sum of values when nums[i:] is split into andv[j:] pieces
    # by trying every possible end position for each piece (literal definition).
    @lru_cache(maxsize=None)
    def f(i, j):
        if j == m:
            return 0 if i == n else INF
        if i == n:
            return INF
        best = INF
        acc = None
        for r in range(i, n):
            acc = nums[r] if acc is None else (acc & nums[r])
            if acc == andv[j]:
                rest = f(r + 1, j + 1)
                if rest < INF:
                    best = min(best, nums[r] + rest)
        return best

    res = f(0, 0)
    if res == INF:
        return json.dumps(-1)
    return json.dumps(res)
